class Solution {
    public int maxProduct(int[] nums) {
        int n = nums.length;
        long best = nums[0];
        for (int i = 0; i < n; i++) {
            long prod = 1;
            for (int j = i; j < n; j++) {
                prod *= nums[j];
                if (prod > best) best = prod;
            }
        }
        return (int) best;
    }
}

class Solution {
    public int maxProduct(int[] nums) {
        long best = Long.MIN_VALUE;
        long prod = 1;
        for (int x : nums) {
            prod *= x;
            if (prod > best) best = prod;
            if (x == 0) prod = 1;
        }
        prod = 1;
        for (int i = nums.length - 1; i >= 0; i--) {
            prod *= nums[i];
            if (prod > best) best = prod;
            if (nums[i] == 0) prod = 1;
        }
        return (int) best;
    }
}

class Solution {
    public int maxProduct(int[] nums) {
        long maxPrev = nums[0];
        long minPrev = nums[0];
        long best = nums[0];

        for (int i = 1; i < nums.length; i++) {
            long x = nums[i];
            long a = maxPrev * x;
            long b = minPrev * x;
            long maxEnd = Math.max(x, Math.max(a, b));
            long minEnd = Math.min(x, Math.min(a, b));
            best = Math.max(best, maxEnd);
            maxPrev = maxEnd;
            minPrev = minEnd;
        }
        return (int) best;
    }
}
